SELECT p.gender, i.first_careunit, i.last_careunit, i.intime, i.outtime, i.los, o.value AS heart_rate, d.icd_code, COUNT(*)::FLOAT / NULLIF(COUNT(DISTINCT i.stay_id), 0) AS proportion_of_stays FROM patients p JOIN icustays i ON p.subject_id = i.subject_id JOIN chartevents o ON i.stay_id = o.stay_id AND o.itemid = 85 AND o.value < 120 JOIN diagnoses_icd d ON i.stay_id = d.hadm_id AND d.icd_code = '410' WHERE p.gender = 'M' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dod)) BETWEEN 62 AND 72 AND i.intime BETWEEN 0 AND 86400 AND i.outtime BETWEEN 0 AND 86400 AND i.los BETWEEN 0 AND 86400 GROUP BY p.gender, i.first_careunit, i.last_careunit, i.intime, i.outtime, i.los, o.value, d.icd_code ORDER BY p.gender, i.first_careunit, i.last_careunit, i.intime, i.outtime, i.los, o.value, d.icd_code NULLS LAST;